<div class="ai-assistant" id="aiAssistant" aria-label="دستیار هوشمند فروشگاه">
<button class="ai-fab" id="aiFab" type="button" aria-expanded="false" aria-controls="aiPanel"><span>✦</span><span class="ai-fab-label">دستیار خرید</span></button>
<section class="ai-panel" id="aiPanel" hidden><header class="ai-head"><div><strong>دستیار هوشمند فروشگاه</strong><small>پاسخ‌ها باید بر پایه شواهد واقعی باشند.</small></div><button type="button" id="aiClose" aria-label="بستن">×</button></header><div class="ai-messages" id="aiMessages"><div class="ai-message ai-message-bot">سلام 👋 دنبال چه فایلی هستید؟</div></div><form class="ai-form" id="aiForm"><textarea id="aiInput" rows="2" maxlength="1000" placeholder="نیازتان را توضیح دهید..."></textarea><div class="ai-actions"><button type="button" id="aiVoice" title="ورودی صوتی">🎙</button><button type="submit">ارسال</button></div></form></section></div>
@push('styles')<style>.ai-assistant{position:fixed;left:22px;bottom:22px;z-index:1200}.ai-fab{display:flex;gap:8px;align-items:center;padding:12px 16px;border:0;border-radius:999px;background:#111827;color:#fff;cursor:pointer;font:inherit;font-weight:800}.ai-fab span:first-child{font-size:20px}.ai-panel{position:absolute;left:0;bottom:58px;width:min(390px,calc(100vw - 30px));height:min(600px,calc(100vh - 100px));background:#fff;border:1px solid #e5e7eb;border-radius:22px;overflow:hidden;box-shadow:0 24px 70px #0f172a33;display:flex;flex-direction:column}.ai-head{padding:16px 18px;display:flex;justify-content:space-between;border-bottom:1px solid #eef0f4}.ai-head strong,.ai-head small{display:block}.ai-head small{font-size:10px;color:#667085;margin-top:4px}.ai-head button{border:0;border-radius:9px;background:#f3f4f6;width:34px;cursor:pointer;font-size:20px}.ai-messages{flex:1;overflow:auto;padding:16px;background:#fafbfe}.ai-message{max-width:88%;padding:11px 13px;border-radius:15px;margin-bottom:10px;font-size:12px;line-height:1.9;white-space:pre-wrap}.ai-message-bot{background:#fff;border:1px solid #e8ebf0}.ai-message-user{margin-right:auto;background:#111827;color:#fff}.ai-form{padding:12px;border-top:1px solid #eef0f4}.ai-form textarea{width:100%;box-sizing:border-box;border:1px solid #dfe3ea;border-radius:13px;padding:10px;font:inherit;resize:none}.ai-actions{display:flex;justify-content:space-between;margin-top:8px}.ai-actions button{border:0;border-radius:10px;padding:9px 14px;cursor:pointer;font:inherit;font-weight:800}.ai-actions button:last-child{background:#111827;color:#fff}.ai-actions button:first-child{background:#f3f4f6}@media(max-width:600px){.ai-assistant{left:12px;bottom:12px}.ai-fab-label{display:none}.ai-fab{width:50px;height:50px;padding:0;justify-content:center}.ai-panel{width:calc(100vw - 24px);height:70vh}}
</style>@endpush
@push('scripts')<script>(function(){const f=document.getElementById('aiFab'),p=document.getElementById('aiPanel'),c=document.getElementById('aiClose'),form=document.getElementById('aiForm'),input=document.getElementById('aiInput'),msgs=document.getElementById('aiMessages'),voice=document.getElementById('aiVoice');if(!f||!p)return;const add=(t,w)=>{const e=document.createElement('div');e.className='ai-message '+(w==='user'?'ai-message-user':'ai-message-bot');e.textContent=t;msgs.appendChild(e);msgs.scrollTop=msgs.scrollHeight;return e};const toggle=o=>{p.hidden=!o;f.setAttribute('aria-expanded',o)};f.onclick=()=>toggle(p.hidden);c.onclick=()=>toggle(false);form.onsubmit=async e=>{e.preventDefault();const text=input.value.trim();if(!text)return;input.value='';add(text,'user');const loading=add('در حال بررسی…','bot');try{const r=await fetch('{{ route('ai.chat') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:JSON.stringify({message:text})});const d=await r.json();loading.remove();const bot=add(d.message||'پاسخ قابل اتکایی در دسترس نیست.','bot');if(d.available!==false){const actions=document.createElement('div');actions.innerHTML='<button type="button" data-rate="5">👍</button> <button type="button" data-rate="1">👎</button>';actions.style.marginTop='6px';bot.appendChild(actions);actions.onclick=async ev=>{const rate=ev.target.dataset.rate;if(!rate)return;await fetch('{{ route('ai.feedback') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:JSON.stringify({rating:Number(rate),type:'response',comment:'بازخورد سریع کاربر',context:{query:text}})});actions.textContent='✓ بازخورد ثبت شد';}}}catch(err){loading.remove();add('ارتباط با دستیار برقرار نشد.','bot')}};const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(SR){const rec=new SR();rec.lang='fa-IR';rec.interimResults=false;voice.onclick=()=>{try{rec.start()}catch(e){}};rec.onresult=e=>{input.value=e.results[0][0].transcript;input.focus()}}else{voice.disabled=true;voice.title='ورودی صوتی در این مرورگر پشتیبانی نمی‌شود'}})();</script>@endpush
